import logging
from ute_common_store import Store


class CoreInterface(object):
    """A class define tdd Core Interface
    """

    def __init__(self):
        """
        """
        self._log = logging.getLogger(__name__)
        self._log.setLevel(logging.DEBUG)
        self._store = Store()
        pass


class ta_kiss_core(CoreInterface):
    """Core interface for Robot Framework.

    BTSCommandLineTools are available on the wiki page: `https://twiki.inside.nsn.com/bin/view/SEM/CommandlineTools`.

    """

    def __init__(self):
        """
        """
        CoreInterface.__init__(self)

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'


